SELECT (SELECT COUNT(*) FROM "stats"."areas" AS "s" WHERE NOT "s"."area_fips" IS NULL AND SUBSTRING("s"."area_fips" FROM 3 FOR 3) <> '000') AS "source_rows", (SELECT COUNT(*) FROM "stats"."areas" AS "s" WHERE (NOT "s"."area_fips" IS NULL AND SUBSTRING("s"."area_fips" FROM 3 FOR 3) <> '000') AND NOT EXISTS(SELECT 1 FROM "stats"."areas" AS "t" WHERE SUBSTRING("s"."area_fips" FROM 1 FOR 2) || '000' = "t"."area_fips" AND SUBSTRING("s"."area_fips" FROM 3 FOR 3) <> '000')) AS "orphans_left", (SELECT COUNT(*) FROM "stats"."areas" AS "t" WHERE NOT EXISTS(SELECT 1 FROM "stats"."areas" AS "s" WHERE SUBSTRING("s"."area_fips" FROM 1 FOR 2) || '000' = "t"."area_fips" AND SUBSTRING("s"."area_fips" FROM 3 FOR 3) <> '000')) AS "orphans_right"
